cssScreen:
.pv{position:relative;

 color:var(--color-text-primary);font:14px/20px Inter,system-ui,sans-serif}
.pv .md-f .bt.pri.pri{background:var(--color-action-primary)!important;color:var(--color-text-inverse)!important;border-color:var(--color-action-primary)!important}
.pad{padding:16px 24px 24px;display:flex;flex-direction:column;gap:16px}
.mpad{padding:12px 16px 96px;display:flex;flex-direction:column;gap:16px}
table{width:100%;border-collapse:collapse}
td,th{padding:11px 16px;border-bottom:1px solid var(--color-border-secondary);text-align:left;font-size:12px}
th{color:var(--color-text-tertiary);font-weight:500;background:var(--color-bg-secondary)}
.tb{border:1px solid var(--color-border-secondary);border-radius:12px;overflow:hidden}
.chip{display:inline-block;font:500 12px/18px Inter;padding:2px 8px;border-radius:999px;background:var(--color-utility-neutral-100)}
.mw{position:absolute;inset:0;background:var(--color-bg-overlay);display:flex;align-items:flex-start;justify-content:center;padding-top:56px;z-index:6}
.md{width:560px;background:var(--color-bg-primary_alt);border-radius:16px;box-shadow:var(--elev-3);display:flex;flex-direction:column}
.md-h{padding:20px 24px 8px;display:flex;gap:12px;align-items:flex-start}
.md-h b{font:600 18px/28px Inter;display:block}
.md-h span{color:var(--color-text-tertiary);font-size:13.5px}
.md-b{padding:12px 24px 8px;display:flex;flex-direction:column;gap:16px}
.md-f{padding:16px 24px 20px;display:flex;justify-content:flex-end;gap:8px}
.inp{height:32px;border:1px solid var(--color-border-input);border-radius:8px;padding:0 10px;display:flex;align-items:center;color:var(--color-text-tertiary);font-size:13.5px}
.ta{height:64px;align-items:flex-start;padding-top:6px}
.card{border:1px solid var(--color-border-secondary);border-radius:12px;padding:16px 20px;display:flex;flex-direction:column;gap:16px}
.card .h{font:600 14px/20px Inter;display:flex;justify-content:space-between;align-items:center}
.cols{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px}
dl{display:grid;grid-template-columns:130px 1fr;gap:6px 12px;margin:0;font-size:12px}
dt{color:var(--color-text-tertiary)}
dd{margin:0}
.mcard{border:1px solid var(--color-border-secondary);border-radius:16px;padding:12px 14px;display:flex;flex-direction:column;gap:2px}
.mcard b{font-size:14px}
.mcard span{color:var(--color-text-tertiary);font-size:12px}
.pt{display:flex;gap:8px;align-items:center;font:600 14px Inter}
.pt .chip{margin-left:auto;font-weight:500}
.cta{position:sticky;bottom:0;height:52px;border:0;border-radius:999px;background:var(--color-action-primary);color:var(--color-text-inverse);font:600 16px Inter;width:100%}
.pv[data-platform=mobile] .cols{grid-template-columns:1fr}
.mf .fu{position:static}
.mf{box-sizing:border-box;position:relative;width:351px;min-height:300px;padding:16px;display:flex;flex-direction:column;gap:16px;background:var(--color-bg-primary);overflow:hidden}
.mf.tall{min-height:520px}
.gl{font:600 12px/16px Inter;color:var(--color-text-tertiary);text-transform:uppercase;letter-spacing:.04em}
.sh0{background:#C9D4E0}.sh1{background:#D8CFC2}.sh2{background:#C4D1C8}.sh3{background:#D3C9D8}
